class ExportSubscriber implements Flow.Subscriber<Row> {
    private Flow.Subscription s;

    public void onSubscribe(Flow.Subscription s) {
        this.s = s;
        s.request(Long.MAX_VALUE);
    }
    public void onNext(Row row) {
        if (row.amount() == null) throw new IllegalStateException("bad row " + row.id());
        file.append(row.toCsv());
    }
    public void onError(Throwable t) { s.request(1); }   // "try again"
    public void onComplete() { file.close(); }
}

